css:
.h360-mess-bill { font-size: 12px; color: #1f272e; }
.h360-mess-bill table { width: 100%; border-collapse: collapse; }
.h360-head td { vertical-align: top; padding-bottom: 10px; }
.h360-head { border-bottom: 2px solid #1f272e; margin-bottom: 12px; }
.h360-logo { width: 70px; }
.h360-logo img { max-height: 60px; max-width: 64px; }
.h360-inst { font-size: 16px; font-weight: 700; }
.h360-muted { color: #6b7280; font-size: 11px; }
.h360-doc-title { text-align: right; font-weight: 700; font-size: 14px; white-space: nowrap; }
.h360-draft { color: #c92a2a; font-size: 11px; margin-top: 4px; }
.h360-meta td { padding: 4px 6px; border: 1px solid #e5e7eb; }
.h360-label { background: #f8f9fa; color: #4b5563; width: 18%; }
.h360-section { margin: 14px 0 6px; font-weight: 700; font-size: 12.5px; }
.h360-calc td { padding: 4px 6px; border-bottom: 1px solid #f1f3f5; }
.h360-calc .h360-total td { font-weight: 700; border-top: 1px solid #adb5bd; }
.h360-calc .h360-grand td { font-weight: 700; font-size: 14px; border-top: 2px solid #1f272e; border-bottom: 2px solid #1f272e; }
.h360-num { text-align: right; white-space: nowrap; }
.h360-lines th { background: #f8f9fa; text-align: left; padding: 5px 6px; border-bottom: 1px solid #dee2e6; }
.h360-lines td { padding: 4px 6px; border-bottom: 1px solid #f1f3f5; }
.h360-small { font-size: 10.5px; }
.h360-words { font-style: italic; margin-top: 4px; }
.h360-note { margin-top: 16px; color: #4b5563; font-size: 11px; }
.h360-sign { margin-top: 48px; }
.h360-sign td { text-align: center; padding-top: 30px; border-top: 1px solid #adb5bd; width: 33%; }
.h360-sign td + td { border-left: 16px solid #fff; }
